import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math_constants.h>
#include <ATen/cuda/CUDAContext.h>

// Max reduction over the middle dimension of a contiguous 3D tensor
// of shape (outer, reduce, inner). Output shape: (outer, inner).
// Each thread computes one output element; threads with consecutive
// inner indices read consecutive memory, so loads are fully coalesced.
__global__ void max_reduce_middle_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    const int outer,
    const int reduce,
    const int inner)
{
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    const int j = blockIdx.x * 32 + lane;
    const int b = blockIdx.y;
    if (b >= outer) return;
    __shared__ float partial[8][32];
    float m = -CUDART_INF_F;
    if (j < inner) {
        const float* base = x + (size_t)b * (size_t)reduce * (size_t)inner + j;
        for (int i = warp; i < reduce; i += 8) {
            m = fmaxf(m, base[(size_t)i * inner]);
        }
    }
    partial[warp][lane] = m;
    __syncthreads();
    if (warp == 0 && j < inner) {
        float r = partial[0][lane];
        #pragma unroll
        for (int w = 1; w < 8; ++w) r = fmaxf(r, partial[w][lane]);
        out[(size_t)b * inner + j] = r;
    }
}

torch::Tensor max_reduce_middle(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(x.dim() == 3, "Input must be 3D");

    auto xc = x.contiguous();
    const int64_t d = (dim % 3 + 3) % 3;

    int64_t outer = 1, reduce = 1, inner = 1;
    for (int64_t k = 0; k < d; ++k) outer *= xc.size(k);
    reduce = xc.size(d);
    for (int64_t k = d + 1; k < 3; ++k) inner *= xc.size(k);

    std::vector<int64_t> out_sizes;
    for (int64_t k = 0; k < 3; ++k) {
        if (k != d) out_sizes.push_back(xc.size(k));
    }
    auto out = torch::empty(out_sizes, xc.options());

    if (outer == 0 || inner == 0) return out;
    if (reduce == 0) {
        out.fill_(-std::numeric_limits<float>::infinity());
        return out;
    }

    const int threads = 256;
    dim3 grid((unsigned)((inner + 31) / 32), (unsigned)outer);
    auto stream = at::cuda::getCurrentCUDAStream();
    max_reduce_middle_kernel<<<grid, threads, 0, stream>>>(
        xc.data_ptr<float>(),
        out.data_ptr<float>(),
        (int)outer, (int)reduce, (int)inner);

    return out;
}
"""

cpp_source = "torch::Tensor max_reduce_middle(torch::Tensor x, int64_t dim);"

_module = load_inline(
    name="max_reduce_middle_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["max_reduce_middle"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Max reduction over a specific dimension using a custom CUDA kernel.
    """

    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _module.max_reduce_middle(x, self.dim)

